law_raw_text_is_never_modified__markers_and_untidy_whitespace_stay_in_the_raw() ->
    {Schema, Symbols} = lawspec_data:context(),
    Text = <<"  See [2]   and [9].\n\n\n\n">>,
    Pool = make_cons_6(
        [make_retrieval_unit([<<"A">>, <<"a">>, make_absent([], Schema)], Schema), []],
        Schema
