    ).

%% |raw text is never modified| property — laws/responses.lawspec:477
law_raw_text_is_never_modified__property() ->
    {Schema, Symbols} = lawspec_data:context(),
    lawspec_beam_search:replay(
        ?LAW_RAW_TEXT_IS_NEVER_MODIFIED,
        [
            <<"(text)">>,
            <<"(data cake.laws.responses::type::RetrievalUnit (ctor cake.laws.responses::type::RetrievalUnit::RetrievalUnit (text) (text) (maybe (int BigUInt 0 _)))) (list (ref cake.laws.responses::type::RetrievalUnit))">>,
            <<"(list (int BigUInt 0 _))">>
        ],
        fun([Text, Pool, Picks]) ->
            lawspec_beam_runtime:require(
                law_raw_text_is_never_modified(Schema, Symbols, [Text, Pool, Picks]),
                ?LAW_RAW_TEXT_IS_NEVER_MODIFIED
