-define(LAW_WARNINGS_ARE_THE_HALLUCINATED_INDICES_IN_ORDER,
    <<"cake.laws.responses::|warnings are the hallucinated indices, in order|">>
).

%% |warnings are the hallucinated indices, in order| — laws/responses.lawspec:516
%% The warnings are exactly one hallucinated-citation warning per marker
%%     index that is not a prompt index, in order of first appearance, and no
%%     other warning.
%% for all (segments :: List (cake.laws.shared::type::Segment)) (pool :: List (cake.laws.responses::type::RetrievalUnit)) (picks :: List (BigUInt)) => match (process (cakeLawsSharedRender (cakeLawsCitationsSmall segments)) (chunksOf (contextOf pool picks))) { cake.laws.responses::type::Processed::Processed lawspecFieldrawText lawspecFieldfinalText lawspecFieldchunkMap lawspecFieldcitations lawspecFieldmediaCount lawspecFieldactions lawspecFieldwarnings -> lawspecFieldwarnings } = warningsOf (cakeLawsCitationsMissingFrom (cakeLawsCitationsDistinctMarkers (cakeLawsCitationsSmall segments)) (cakeLawsCitationsPromptMapOf (contextOf pool picks))) end for all
law_warnings_are_the_hallucinated_indices_in_order(Schema, Symbols, [Segments, Pool, Picks]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_definitions:process(
                Schema,
                Symbols,
                lawspec_definitions:cake_laws_shared_render_3(
                    Schema,
                    Symbols,
                    lawspec_definitions:cake_laws_citations_small(Schema, Symbols, Segments)
                ),
                lawspec_definitions:chunks_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                )
            ),
            #{
                <<"cake.laws.responses::type::Processed::Processed">> => fun(
                    [_RawText, _FinalText, _ChunkMap, _Citations, _MediaCount, _Actions, Warnings]
                ) ->
                    Warnings
                end
            }
        ),
        lawspec_definitions:warnings_of(
            Schema,
            Symbols,
            lawspec_definitions:cake_laws_citations_missing_from(
                Schema,
                Symbols,
                lawspec_definitions:cake_laws_citations_distinct_markers(
                    Schema,
                    Symbols,
                    lawspec_definitions:cake_laws_citations_small(Schema, Symbols, Segments)
                ),
                lawspec_definitions:cake_laws_citations_prompt_map_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                )
            )
        ),
        ?LAW_WARNINGS_ARE_THE_HALLUCINATED_INDICES_IN_ORDER
    ).

