%% |warnings are the hallucinated indices, in order| example |later markers stay later, and [0] is hallucinated| — laws/responses.lawspec:538
law_warnings_are_the_hallucinated_indices_in_order__later_markers_stay_later_and_0_is_hallucinated() ->
    {Schema, Symbols} = lawspec_data:context(),
    Segments = make_cons_9(
        [
            make_marker([9], Schema),
            make_cons_9(
                [
                    make_plain([<<" ">>], Schema),
                    make_cons_9(
                        [
                            make_marker([1], Schema),
                            make_cons_9(
                                [
                                    make_plain([<<" ">>], Schema),
                                    make_cons_9(
                                        [
                                            make_marker([0], Schema),
                                            make_cons_9(
                                                [
                                                    make_plain([<<" ">>], Schema),
                                                    make_cons_9(
                                                        [make_marker([9], Schema), []],
                                                        Schema
                                                    )
                                                ],
                                                Schema
                                            )
                                        ],
                                        Schema
                                    )
                                ],
                                Schema
                            )
                        ],
                        Schema
                    )
                ],
                Schema
            )
        ],
        Schema
    ),
    Pool = make_cons_6(
        [make_retrieval_unit([<<"A">>, <<"a">>, make_absent([], Schema)], Schema), []],
        Schema
    ),
    Picks = [0],
    lawspec_beam_runtime:require(
        law_warnings_are_the_hallucinated_indices_in_order(
            Schema,
            Symbols,
            [Segments, Pool, Picks]
        ),
        ?LAW_WARNINGS_ARE_THE_HALLUCINATED_INDICES_IN_ORDER
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:cake_laws_shared_render_3(Schema, Symbols, Segments),
        <<"[9] [1] [0] [9]">>,
        <<"|warnings are the hallucinated indices, in order| example |later markers stay later, and [0] is hallucinated| — laws/responses.lawspec:538"/utf8>>
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_definitions:process(
                Schema,
                Symbols,
                lawspec_definitions:cake_laws_shared_render_3(Schema, Symbols, Segments),
                lawspec_definitions:chunks_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                )
            ),
            #{
                <<"cake.laws.responses::type::Processed::Processed">> => fun(
                    [_RawText, _FinalText, _ChunkMap, _Citations, _MediaCount, _Actions, Warnings]
                ) ->
                    Warnings
                end
            }
        ),
        make_cons_7(
            [
                make_hallucinated_citation([9], Schema),
                make_cons_7([make_hallucinated_citation([0], Schema), []], Schema)
            ],
            Schema
        ),
        <<"|warnings are the hallucinated indices, in order| example |later markers stay later, and [0] is hallucinated| — laws/responses.lawspec:539"/utf8>>
    ).

