-define(LAW_EVERY_CITATION_RESOLVES_THROUGH_THE_CHUNK_MAP,
    <<"cake.laws.responses::|every citation resolves through the chunk map|">>
).

%% |every citation resolves through the chunk map| — laws/responses.lawspec:544
%% Each citation's old index is a prompt index, its metadata is the chunk
%%     map's metadata for that index, and no two citations share a new index.
%% for all (segments :: List (cake.laws.shared::type::Segment)) (pool :: List (cake.laws.responses::type::RetrievalUnit)) (picks :: List (BigUInt)) => allResolve (match (process (cakeLawsSharedRender (cakeLawsCitationsSmall segments)) (chunksOf (contextOf pool picks))) { cake.laws.responses::type::Processed::Processed lawspecFieldrawText lawspecFieldfinalText lawspecFieldchunkMap lawspecFieldcitations lawspecFieldmediaCount lawspecFieldactions lawspecFieldwarnings -> lawspecFieldcitations }) (cakeLawsCitationsPromptMapOf (contextOf pool picks)) = true and distinct (newIndicesOf (match (process (cakeLawsSharedRender (cakeLawsCitationsSmall segments)) (chunksOf (contextOf pool picks))) { cake.laws.responses::type::Processed::Processed lawspecFieldrawText lawspecFieldfinalText lawspecFieldchunkMap lawspecFieldcitations lawspecFieldmediaCount lawspecFieldactions lawspecFieldwarnings -> lawspecFieldcitations })) = true end for all
law_every_citation_resolves_through_the_chunk_map(Schema, Symbols, [Segments, Pool, Picks]) ->
    (lawspec_beam_runtime:assert_equal(
        lawspec_definitions:all_resolve(
            Schema,
            Symbols,
            lawspec_beam_schema:match(
                lawspec_definitions:process(
                    Schema,
                    Symbols,
                    lawspec_definitions:cake_laws_shared_render_3(
                        Schema,
                        Symbols,
                        lawspec_definitions:cake_laws_citations_small(Schema, Symbols, Segments)
                    ),
                    lawspec_definitions:chunks_of(
                        Schema,
                        Symbols,
                        lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                    )
                ),
                #{
                    <<"cake.laws.responses::type::Processed::Processed">> => fun(
                        [
                            _RawText,
                            _FinalText,
                            _ChunkMap,
                            Citations,
                            _MediaCount,
                            _Actions,
                            _Warnings
                        ]
                    ) ->
                        Citations
                    end
                }
            ),
            lawspec_definitions:cake_laws_citations_prompt_map_of(
                Schema,
                Symbols,
                lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
            )
