-define(LAW_NEW_INDICES_COUNT_FROM_1_IN_CITATION_ORDER,
    <<"cake.laws.responses::|new indices count from 1 in citation order|">>
).

%% |new indices count from 1 in citation order| — laws/responses.lawspec:563
%% The citations' new indices are exactly 1..K for K citations, in the order
%%     the citations are listed: no gaps, even when a hallucinated marker comes
%%     before a valid one.
%% for all (segments :: List (cake.laws.shared::type::Segment)) (pool :: List (cake.laws.responses::type::RetrievalUnit)) (picks :: List (BigUInt)) => newIndicesOf (match (process (cakeLawsSharedRender (cakeLawsCitationsSmall segments)) (chunksOf (contextOf pool picks))) { cake.laws.responses::type::Processed::Processed lawspecFieldrawText lawspecFieldfinalText lawspecFieldchunkMap lawspecFieldcitations lawspecFieldmediaCount lawspecFieldactions lawspecFieldwarnings -> lawspecFieldcitations }) = countingFrom 1 ((Length(match (process (cakeLawsSharedRender (cakeLawsCitationsSmall segments)) (chunksOf (contextOf pool picks))) { cake.laws.responses::type::Processed::Processed lawspecFieldrawText lawspecFieldfinalText lawspecFieldchunkMap lawspecFieldcitations lawspecFieldmediaCount lawspecFieldactions lawspecFieldwarnings -> lawspecFieldcitations }) :: BigUInt)) end for all
law_new_indices_count_from_1_in_citation_order(Schema, Symbols, [Segments, Pool, Picks]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:new_indices_of(
            Schema,
            Symbols,
            lawspec_beam_schema:match(
                lawspec_definitions:process(
                    Schema,
                    Symbols,
                    lawspec_definitions:cake_laws_shared_render_3(
                        Schema,
                        Symbols,
                        lawspec_definitions:cake_laws_citations_small(Schema, Symbols, Segments)
                    ),
                    lawspec_definitions:chunks_of(
                        Schema,
                        Symbols,
                        lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                    )
                ),
                #{
                    <<"cake.laws.responses::type::Processed::Processed">> => fun(
                        [
                            _RawText,
                            _FinalText,
                            _ChunkMap,
                            Citations,
                            _MediaCount,
                            _Actions,
                            _Warnings
                        ]
                    ) ->
                        Citations
                    end
                }
            )
        ),
        lawspec_definitions:counting_from(
            Schema,
            Symbols,
            1,
            lawspec_beam_schema:validate(
                lawspec_beam_scalar:convert(
                    lawspec_beam_runtime:helper(
                        <<"length">>,
                        [
                            lawspec_beam_schema:match(
                                lawspec_definitions:process(
                                    Schema,
                                    Symbols,
                                    lawspec_definitions:cake_laws_shared_render_3(
                                        Schema,
                                        Symbols,
                                        lawspec_definitions:cake_laws_citations_small(
                                            Schema,
                                            Symbols,
                                            Segments
                                        )
                                    ),
                                    lawspec_definitions:chunks_of(
                                        Schema,
                                        Symbols,
                                        lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                                    )
                                ),
                                #{
                                    <<"cake.laws.responses::type::Processed::Processed">> => fun(
                                        [
                                            _RawText,
                                            _FinalText,
                                            _ChunkMap,
                                            Citations,
                                            _MediaCount,
                                            _Actions,
                                            _Warnings
                                        ]
                                    ) ->
                                        Citations
                                    end
                                }
                            )
                        ],
                        [<<"List cake.laws.responses::type::Cited">>],
                        64
                    ),
                    type_big_u_int(),
                    64
                ),
                type_big_u_int(),
                Schema
            )
        ),
        ?LAW_NEW_INDICES_COUNT_FROM_1_IN_CITATION_ORDER
    ).

