%% |new indices count from 1 in citation order| example |a hallucinated marker before a valid one leaves no gap| — laws/responses.lawspec:589
law_new_indices_count_from_1_in_citation_order__a_hallucinated_marker_before_a_valid_one_leaves() ->
    {Schema, Symbols} = lawspec_data:context(),
    Segments = make_cons_9(
        [
            make_marker([9], Schema),
            make_cons_9(
                [
                    make_plain([<<" then ">>], Schema),
                    make_cons_9(
                        [
                            make_marker([1], Schema),
                            make_cons_9([make_plain([<<".">>], Schema), []], Schema)
                        ],
                        Schema
                    )
                ],
                Schema
            )
        ],
        Schema
    ),
    Pool = make_cons_6(
        [
            make_retrieval_unit(
                [<<"Programming Elixir — Page 1"/utf8>>, <<"One">>, make_absent([], Schema)],
                Schema
            ),
            []
        ],
        Schema
    ),
    Picks = [0],
    lawspec_beam_runtime:require(
        law_new_indices_count_from_1_in_citation_order(Schema, Symbols, [Segments, Pool, Picks]),
        ?LAW_NEW_INDICES_COUNT_FROM_1_IN_CITATION_ORDER
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:cake_laws_shared_render_3(Schema, Symbols, Segments),
        <<"[9] then [1].">>,
        <<"|new indices count from 1 in citation order| example |a hallucinated marker before a valid one leaves no gap| — laws/responses.lawspec:589"/utf8>>
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_definitions:process(
                Schema,
                Symbols,
                lawspec_definitions:cake_laws_shared_render_3(Schema, Symbols, Segments),
                lawspec_definitions:chunks_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                )
            ),
            #{
                <<"cake.laws.responses::type::Processed::Processed">> => fun(
                    [_RawText, _FinalText, _ChunkMap, Citations, _MediaCount, _Actions, _Warnings]
                ) ->
                    Citations
                end
            }
        ),
        make_cons_4(
            [
                make_cited(
                    [
                        1,
                        1,
                        make_citable_meta(
                            [
                                <<"unit-0">>,
                                <<"Programming Elixir — Page 1"/utf8>>,
                                <<"One">>,
                                make_absent_2([], Schema)
                            ],
                            Schema
                        )
                    ],
                    Schema
                ),
                []
            ],
            Schema
        ),
        <<"|new indices count from 1 in citation order| example |a hallucinated marker before a valid one leaves no gap| — laws/responses.lawspec:590"/utf8>>
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_definitions:process(
                Schema,
                Symbols,
                lawspec_definitions:cake_laws_shared_render_3(Schema, Symbols, Segments),
                lawspec_definitions:chunks_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                )
