%% |one citation per retrieval unit, in first-appearance order| — laws/responses.lawspec:605
%% The citations are the valid markers in order of first appearance, less
%%     every later marker that resolves to an already cited unit's id: two prompt
%%     indices that hold the same unit give one citation, which keeps the old
%%     index of the marker that appeared first.
%% for all (segments :: List (cake.laws.shared::type::Segment)) (pool :: List (cake.laws.responses::type::RetrievalUnit)) (picks :: List (BigUInt)) => unnumbered (match (process (cakeLawsSharedRender (cakeLawsCitationsSmall segments)) (chunksOf (contextOf pool picks))) { cake.laws.responses::type::Processed::Processed lawspecFieldrawText lawspecFieldfinalText lawspecFieldchunkMap lawspecFieldcitations lawspecFieldmediaCount lawspecFieldactions lawspecFieldwarnings -> lawspecFieldcitations }) = firstPerUnit (cakeLawsCitationsCitationsOf (cakeLawsCitationsDistinctMarkers (cakeLawsCitationsSmall segments)) (cakeLawsCitationsPromptMapOf (contextOf pool picks))) end for all
law_one_citation_per_retrieval_unit_in_first(Schema, Symbols, [Segments, Pool, Picks]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:unnumbered(
            Schema,
            Symbols,
            lawspec_beam_schema:match(
                lawspec_definitions:process(
                    Schema,
                    Symbols,
                    lawspec_definitions:cake_laws_shared_render_3(
                        Schema,
                        Symbols,
                        lawspec_definitions:cake_laws_citations_small(Schema, Symbols, Segments)
                    ),
                    lawspec_definitions:chunks_of(
                        Schema,
                        Symbols,
                        lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                    )
                ),
                #{
                    <<"cake.laws.responses::type::Processed::Processed">> => fun(
                        [
                            _RawText,
                            _FinalText,
                            _ChunkMap,
                            Citations,
                            _MediaCount,
                            _Actions,
                            _Warnings
                        ]
                    ) ->
                        Citations
                    end
                }
            )
        ),
        lawspec_definitions:first_per_unit(
            Schema,
            Symbols,
            lawspec_definitions:cake_laws_citations_citations_of(
                Schema,
                Symbols,
                lawspec_definitions:cake_laws_citations_distinct_markers(
                    Schema,
                    Symbols,
                    lawspec_definitions:cake_laws_citations_small(Schema, Symbols, Segments)
                ),
                lawspec_definitions:cake_laws_citations_prompt_map_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                )
            )
        ),
        ?LAW_ONE_CITATION_PER_RETRIEVAL_UNIT_IN_FIRST
    ).

