%% |one citation per retrieval unit, in first-appearance order| example |one unit at two prompt indices is cited once| — laws/responses.lawspec:631
law_one_citation_per_retrieval_unit_in_first__one_unit_at_two_prompt_indices_is_cited_once() ->
    {Schema, Symbols} = lawspec_data:context(),
    Segments = make_cons_9(
        [
            make_marker([2], Schema),
            make_cons_9(
                [
                    make_plain([<<" and ">>], Schema),
                    make_cons_9([make_marker([1], Schema), []], Schema)
                ],
                Schema
            )
        ],
        Schema
    ),
    Pool = make_cons_6(
        [
            make_retrieval_unit(
                [<<"Programming Elixir — Page 1"/utf8>>, <<"One">>, make_present([0], Schema)],
                Schema
            ),
            []
        ],
        Schema
    ),
    Picks = [0, 0],
    lawspec_beam_runtime:require(
        law_one_citation_per_retrieval_unit_in_first(Schema, Symbols, [Segments, Pool, Picks]),
        ?LAW_ONE_CITATION_PER_RETRIEVAL_UNIT_IN_FIRST
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:cake_laws_shared_render_3(Schema, Symbols, Segments),
        <<"[2] and [1]">>,
        <<"|one citation per retrieval unit, in first-appearance order| example |one unit at two prompt indices is cited once| — laws/responses.lawspec:631"/utf8>>
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_definitions:process(
                Schema,
                Symbols,
                lawspec_definitions:cake_laws_shared_render_3(Schema, Symbols, Segments),
                lawspec_definitions:chunks_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                )
            ),
            #{
                <<"cake.laws.responses::type::Processed::Processed">> => fun(
                    [_RawText, _FinalText, _ChunkMap, Citations, _MediaCount, _Actions, _Warnings]
                ) ->
                    Citations
                end
            }
        ),
        make_cons_4(
            [
                make_cited(
                    [
                        2,
                        1,
                        make_citable_meta(
                            [
                                <<"unit-0">>,
                                <<"Programming Elixir — Page 1"/utf8>>,
                                <<"One">>,
                                make_present_2([<<"books/source-0.pdf">>], Schema)
                            ],
                            Schema
                        )
                    ],
                    Schema
                ),
                []
            ],
            Schema
        ),
        <<"|one citation per retrieval unit, in first-appearance order| example |one unit at two prompt indices is cited once| — laws/responses.lawspec:632"/utf8>>
    ).

