law_one_citation_per_retrieval_unit_in_first__different_units_keep_their_own_citations() ->
    {Schema, Symbols} = lawspec_data:context(),
    Segments = make_cons_9(
        [
            make_marker([2], Schema),
            make_cons_9(
                [
                    make_plain([<<" and ">>], Schema),
                    make_cons_9(
                        [
                            make_marker([1], Schema),
