                                        'Elixir.LawSpec.Beam.StreamData':exactly(
                                            [Segments, Pool, Picks]
                                        )
                                    end
                                )
                            end
                        )
                    end
                )
            ),
            fun(Values) -> law_one_citation_per_retrieval_unit_in_first(Schema, Symbols, Values) end
        ),
        [{numtests, 100}, {constraint_tries, 10000}, {max_shrinks, 1000}]
    ).

-define(LAW_FINAL_TEXT_SHOWS_EACH_MARKER_AS_ITS_CITATION_S,
    <<"cake.laws.responses::|final text shows each marker as its citation's new index|">>
).

%% |final text shows each marker as its citation's new index| — laws/responses.lawspec:663
%% In the final text every valid marker is rewritten to the new index of
%%     the citation of the unit it resolves to, so two markers for one unit show
%%     the same number, and every hallucinated marker is removed. Runs of spaces
%%     then become one space, three or more newlines become two, and the ends
%%     are trimmed. Words are unchanged.
%% for all (pieces :: List (cake.laws.responses::type::Piece)) (pool :: List (cake.laws.responses::type::RetrievalUnit)) (picks :: List (BigUInt)) => match (process (textOf (smallPieces pieces)) (chunksOf (contextOf pool picks))) { cake.laws.responses::type::Processed::Processed lawspecFieldrawText lawspecFieldfinalText lawspecFieldchunkMap lawspecFieldcitations lawspecFieldmediaCount lawspecFieldactions lawspecFieldwarnings -> lawspecFieldfinalText } = finalTextOf (smallPieces pieces) (cakeLawsCitationsPromptMapOf (contextOf pool picks)) (match (process (textOf (smallPieces pieces)) (chunksOf (contextOf pool picks))) { cake.laws.responses::type::Processed::Processed lawspecFieldrawText lawspecFieldfinalText lawspecFieldchunkMap lawspecFieldcitations lawspecFieldmediaCount lawspecFieldactions lawspecFieldwarnings -> lawspecFieldcitations }) end for all
law_final_text_shows_each_marker_as_its_citation_s(Schema, Symbols, [Pieces, Pool, Picks]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_definitions:process(
                Schema,
                Symbols,
                lawspec_definitions:text_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:small_pieces(Schema, Symbols, Pieces)
                ),
                lawspec_definitions:chunks_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                )
            ),
            #{
                <<"cake.laws.responses::type::Processed::Processed">> => fun(
                    [_RawText, FinalText, _ChunkMap, _Citations, _MediaCount, _Actions, _Warnings]
                ) ->
                    FinalText
                end
            }
        ),
        lawspec_definitions:final_text_of(
            Schema,
            Symbols,
            lawspec_definitions:small_pieces(Schema, Symbols, Pieces),
            lawspec_definitions:cake_laws_citations_prompt_map_of(
                Schema,
                Symbols,
                lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
            ),
            lawspec_beam_schema:match(
                lawspec_definitions:process(
                    Schema,
                    Symbols,
                    lawspec_definitions:text_of(
                        Schema,
                        Symbols,
                        lawspec_definitions:small_pieces(Schema, Symbols, Pieces)
                    ),
                    lawspec_definitions:chunks_of(
                        Schema,
                        Symbols,
                        lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                    )
                ),
                #{
                    <<"cake.laws.responses::type::Processed::Processed">> => fun(
                        [
                            _RawText,
                            _FinalText,
                            _ChunkMap,
                            Citations,
                            _MediaCount,
                            _Actions,
                            _Warnings
                        ]
                    ) ->
                        Citations
                    end
                }
            )
        ),
        ?LAW_FINAL_TEXT_SHOWS_EACH_MARKER_AS_ITS_CITATION_S
    ).

