-define(LAW_ONE_DOWNLOAD_PER_CITED_SOURCE_IN_FIRST_CITATION,
    <<"cake.laws.responses::|one download per cited source, in first-citation order|">>
).

%% |one download per cited source, in first-citation order| — laws/responses.lawspec:728
%% The actions are one download per distinct source among the valid
%%     citations, in order of first citation, each labelled as the first citation
%%     of its source is. A citation with no source gives no action.
%% for all (segments :: List (cake.laws.shared::type::Segment)) (pool :: List (cake.laws.responses::type::RetrievalUnit)) (picks :: List (BigUInt)) => match (process (cakeLawsSharedRender (cakeLawsCitationsSmall segments)) (chunksOf (contextOf pool picks))) { cake.laws.responses::type::Processed::Processed lawspecFieldrawText lawspecFieldfinalText lawspecFieldchunkMap lawspecFieldcitations lawspecFieldmediaCount lawspecFieldactions lawspecFieldwarnings -> lawspecFieldactions } = downloadsOf (cakeLawsCitationsCitationsOf (cakeLawsCitationsDistinctMarkers (cakeLawsCitationsSmall segments)) (cakeLawsCitationsPromptMapOf (contextOf pool picks))) end for all
law_one_download_per_cited_source_in_first_citation(Schema, Symbols, [Segments, Pool, Picks]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_definitions:process(
                Schema,
                Symbols,
                lawspec_definitions:cake_laws_shared_render_3(
                    Schema,
                    Symbols,
                    lawspec_definitions:cake_laws_citations_small(Schema, Symbols, Segments)
                ),
                lawspec_definitions:chunks_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                )
            ),
            #{
                <<"cake.laws.responses::type::Processed::Processed">> => fun(
                    [_RawText, _FinalText, _ChunkMap, _Citations, _MediaCount, Actions, _Warnings]
                ) ->
                    Actions
                end
            }
        ),
        lawspec_definitions:downloads_of(
            Schema,
            Symbols,
            lawspec_definitions:cake_laws_citations_citations_of(
                Schema,
                Symbols,
                lawspec_definitions:cake_laws_citations_distinct_markers(
                    Schema,
                    Symbols,
                    lawspec_definitions:cake_laws_citations_small(Schema, Symbols, Segments)
                ),
                lawspec_definitions:cake_laws_citations_prompt_map_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                )
            )
        ),
        ?LAW_ONE_DOWNLOAD_PER_CITED_SOURCE_IN_FIRST_CITATION
    ).

