%% |one download per cited source, in first-citation order| example |two pages of one book, cited after another book| — laws/responses.lawspec:757
law_one_download_per_cited_source_in_first_citation__two_pages_of_one_book_cited_after_another_book() ->
    {Schema, Symbols} = lawspec_data:context(),
    Segments = make_cons_9(
        [
            make_marker([3], Schema),
            make_cons_9(
                [
                    make_plain([<<" ">>], Schema),
                    make_cons_9(
                        [
                            make_marker([1], Schema),
                            make_cons_9(
                                [
                                    make_plain([<<" ">>], Schema),
                                    make_cons_9(
                                        [
                                            make_marker([4], Schema),
                                            make_cons_9(
                                                [
                                                    make_plain([<<" ">>], Schema),
                                                    make_cons_9(
                                                        [make_marker([2], Schema), []],
                                                        Schema
                                                    )
                                                ],
                                                Schema
                                            )
                                        ],
                                        Schema
                                    )
                                ],
                                Schema
                            )
                        ],
                        Schema
                    )
                ],
                Schema
            )
        ],
        Schema
    ),
    Pool = make_cons_6(
        [
            make_retrieval_unit([<<"Alpha, p. 1">>, <<"a">>, make_present([0], Schema)], Schema),
            make_cons_6(
                [
                    make_retrieval_unit([<<"Notes">>, <<"n">>, make_absent([], Schema)], Schema),
                    make_cons_6(
                        [
                            make_retrieval_unit(
                                [<<"Beta, p. 2">>, <<"b">>, make_present([1], Schema)],
                                Schema
                            ),
                            make_cons_6(
                                [
                                    make_retrieval_unit(
                                        [<<"Alpha, p. 3">>, <<"c">>, make_present([0], Schema)],
                                        Schema
                                    ),
                                    []
                                ],
                                Schema
                            )
                        ],
                        Schema
                    )
                ],
                Schema
            )
        ],
        Schema
    ),
    Picks = [0, 1, 2, 3],
    lawspec_beam_runtime:require(
        law_one_download_per_cited_source_in_first_citation(
            Schema,
            Symbols,
            [Segments, Pool, Picks]
        ),
        ?LAW_ONE_DOWNLOAD_PER_CITED_SOURCE_IN_FIRST_CITATION
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_definitions:process(
                Schema,
                Symbols,
                lawspec_definitions:cake_laws_shared_render_3(Schema, Symbols, Segments),
                lawspec_definitions:chunks_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:context_of(Schema, Symbols, Pool, Picks)
                )
            ),
            #{
                <<"cake.laws.responses::type::Processed::Processed">> => fun(
                    [_RawText, _FinalText, _ChunkMap, _Citations, _MediaCount, Actions, _Warnings]
                ) ->
                    Actions
                end
            }
        ),
        make_cons_3(
            [
                make_action(
                    [make_download([], Schema), <<"Beta, p. 2">>, <<"books/source-1.pdf">>],
                    Schema
                ),
                make_cons_3(
                    [
                        make_action(
                            [
                                make_download([], Schema),
                                <<"Alpha, p. 1">>,
                                <<"books/source-0.pdf">>
                            ],
                            Schema
                        ),
                        []
                    ],
                    Schema
                )
            ],
            Schema
        ),
        <<"|one download per cited source, in first-citation order| example |two pages of one book, cited after another book| — laws/responses.lawspec:757"/utf8>>
    ).

